const CHHATTISGARHI_STATS=[{label:"Speakers",value:"~18 Million"},{label:"Language Family",value:"Indo-Aryan"},{label:"Script",value:"Devanagari"},{label:"Primary Region",value:"Chhattisgarh"}],CHHATTISGARHI_GREETING={devanagari:"जोहार",transliteration:"Johār",meaning:"The most distinctive and widely recognized Chhattisgarhi greeting, used as both hello and a respectful salutation — deeply rooted in Chhattisgarh's rural and tribal-influenced culture, and often used as a regional identity marker.",folkVariant:{devanagari:"राम राम",transliteration:"Rām Rām",meaning:"A warm, widely used everyday greeting across Chhattisgarh, common in both rural and urban settings alongside Johar."},note:"Chhattisgarhi does not have a dedicated browser text-to-speech voice, so pronunciation below plays using the closest available Hindi (Devanagari-script) voice as an approximation — not a native Chhattisgarhi recording. Actual Chhattisgarhi speech has its own distinct rhythm and vowel quality."},CHHATTISGARHI_WORDS=[{devanagari:"पानी",translit:"Pānī",meaning:"Water",note:"Shared Indo-Aryan root with Hindi, pronounced with regional vowel softening."},{devanagari:"बने",translit:"Bane",meaning:"Good / Fine",note:"A distinctly Chhattisgarhi word for 'good' or 'well', different from Hindi's 'accha' — one of the most recognizable Chhattisgarhi-specific terms."},{devanagari:"घर",translit:"Ghar",meaning:"House / Home",note:"Common Indo-Aryan vocabulary shared across most languages of central India."},{devanagari:"दाई",translit:"Dāī",meaning:"Mother",note:"The characteristic Chhattisgarhi term for mother, distinct from Hindi 'maa'."},{devanagari:"ददा",translit:"Dadā",meaning:"Father / Elder brother",note:"Used for father in many Chhattisgarhi-speaking families, and for elder brother in others depending on regional and family usage."},{devanagari:"कईसे",translit:"Kaīse",meaning:"How",note:"The Chhattisgarhi form of Hindi 'kaise', reflecting the dialect's characteristic vowel patterns."},{devanagari:"खाना",translit:"Khānā",meaning:"Food / To eat",note:"Shared root with Hindi and other Indo-Aryan languages of central India."},{devanagari:"दिन",translit:"Din",meaning:"Day",note:"Common Indo-Aryan vocabulary tracing back to Sanskrit 'dina'."},{devanagari:"मयारू",translit:"Mayārū",meaning:"Dear / Beloved",note:"A distinctly Chhattisgarhi term of affection, frequently heard in Chhattisgarhi folk songs and poetry."},{devanagari:"जल्दी",translit:"Jaldī",meaning:"Quickly",note:"Shared across neighboring Indo-Aryan languages, used identically in everyday Chhattisgarhi speech."}],CHHATTISGARHI_SCRIPT={intro:"Chhattisgarhi is written in the Devanagari script, the same script used for Hindi and Sanskrit, which has supported its growing body of printed literature, textbooks, and regional media.",facts:[{title:"Devanagari Standard",detail:"Modern Chhattisgarhi books, newspapers, and official regional-language materials are printed in standard Devanagari, aiding mutual readability with Hindi."},{title:"Tribal & Regional Vocabulary Layer",detail:"Chhattisgarhi has absorbed vocabulary from neighboring tribal languages of central India, including Gondi and Halbi, reflecting the region's cultural diversity."},{title:"Official Regional Recognition",detail:"Chhattisgarhi holds official second-language status within the state of Chhattisgarh, used alongside Hindi in certain state government and educational contexts."}]},CHHATTISGARHI_CLASSIFICATION={family:"Indo-European → Indo-Iranian → Indo-Aryan → Central Zone (Eastern Hindi group)",siblings:["Awadhi","Bagheli","Standard Hindi (as a literary register)"],note:"Chhattisgarhi belongs to the Eastern Hindi group of Central Zone Indo-Aryan languages, closely related to Awadhi and Bagheli. Its geographic isolation within the Chhattisgarh plains historically allowed it to develop distinctive vocabulary and grammar separate from standard Hindi."},CHHATTISGARHI_REGION={intro:"Chhattisgarhi is spoken across the state of Chhattisgarh, particularly in the fertile central plains region historically known as the 'rice bowl' of central India, with pockets of speakers extending into neighboring Odisha, Jharkhand, and Madhya Pradesh.",districts:["Raipur","Bilaspur","Durg","Rajnandgaon","Raigarh","Janjgir-Champa","Mahasamund","Dhamtari","Kanker"]},CHHATTISGARHI_HERITAGE=[{title:"Chhattisgarhi Folk Music & Dance",desc:"The region's folk traditions include Pandwani (an epic storytelling performance based on the Mahabharata), Karma dance, and Suwa songs — living traditions still performed at village festivals across Chhattisgarh today."},{title:"Pandwani Storytelling",desc:"A distinctive musical narration style recounting episodes from the Mahabharata in Chhattisgarhi, performed solo with a tambura, made internationally known through artists like Teejan Bai, a Padma Vibhushan recipient."},{title:"Chhattisgarhi Cinema",desc:"A small but growing regional film industry produces Chhattisgarhi-language films, contributing to the language's visibility and everyday cultural presence among younger generations."},{title:"Rice Culture & Harvest Festivals",desc:"As the historical rice-growing heartland of central India, Chhattisgarh's agrarian calendar shapes many of its Chhattisgarhi folk songs and festivals, particularly those tied to sowing and harvest seasons."}],CHHATTISGARHI_REFERENCES=[{text:"Grierson, George A. Linguistic Survey of India, Vol. VI: Indo-Aryan Family, Eastern Group. 1904.",url:"https://archive.org/"},{text:"Government of Chhattisgarh — Chhattisgarhi Language and Culture Resources.",url:"https://chhattisgarh.gov.in/"},{text:"Census of India — Statement of Language and Mother Tongue Strength.",url:"https://censusindia.gov.in/"},{text:"People's Linguistic Survey of India (PLSI) — Chhattisgarhi Volume.",url:"https://peopleslinguisticsurvey.org/"}];